from author import Author
from storage import LibraryStorage

# Global list to store all authors
authors = []

# Initialize storage
storage = LibraryStorage()

def display_main_menu():
    """Display the initial role selection menu."""
    print("\n=== Library Management System ===")
    print("1. Enter as Reader")
    print("2. Enter as Author")
    print("3. Exit")
    print("===========================")

def display_reader_menu():
    """Display the menu options for readers."""
    print("\n=== Reader Menu ===")
    print("1. View all available books")
    print("2. Search books by author")
    print("3. Search books by genre")
    print("4. View all authors")
    print("5. Borrow a book")
    print("6. Return a book")
    print("7. View my borrowed books")
    print("8. Return to main menu")
    print("==================")

def display_author_menu():
    """Display the menu options for authors."""
    print("\n=== Author Menu ===")
    print("1. Add a new book")
    print("2. Display my books")
    print("3. Update book information")
    print("4. Remove a book")
    print("5. Return to main menu")
    print("==================")

def get_book_info():
    """Get book information from user input."""
    title = input("Enter book title: ")
    year = input("Enter publication year: ")
    genre = input("Enter book genre: ")
    pages = input("Enter number of pages: ")
    isbn = input("Enter ISBN (required for borrowing): ")

    # Create a dictionary with only valid inputs
    book_info = {}
    if year.isdigit():
        book_info['year'] = int(year)
    if genre:
        book_info['genre'] = genre
    if pages.isdigit():
        book_info['pages'] = int(pages)
    if isbn:
        book_info['isbn'] = isbn

    return title, book_info

def update_book_menu(author):
    """Menu for updating book information."""
    if not author.books:
        print("\nNo books available to update!")
        return

    print("\nCurrent books:")
    author.display_books()

    title = input("\nEnter the title of the book to update: ")

    # Check if book exists
    book_exists = any(book['title'] == title for book in author.books)
    if not book_exists:
        print(f"Book '{title}' not found!")
        return

    print("\nWhat information would you like to update?")
    print("1. Year")
    print("2. Genre")
    print("3. Pages")
    print("4. ISBN")
    print("5. Add new attribute")

    choice = input("Enter your choice (1-5): ")

    update_info = {}
    if choice == '1':
        year = input("Enter new year: ")
        if year.isdigit():
            update_info['year'] = int(year)
    elif choice == '2':
        update_info['genre'] = input("Enter new genre: ")
    elif choice == '3':
        pages = input("Enter new number of pages: ")
        if pages.isdigit():
            update_info['pages'] = int(pages)
    elif choice == '4':
        update_info['isbn'] = input("Enter new ISBN: ")
    elif choice == '5':
        attr_name = input("Enter new attribute name: ")
        attr_value = input(f"Enter value for {attr_name}: ")
        update_info[attr_name] = attr_value

    if update_info:
        author.update_book(title, **update_info)
        storage.save_library_data(authors)  # Save after updating

def display_all_books():
    """Display all books across all authors."""
    if not authors:
        print("\nNo books available in the library!")
        return

    print("\n=== All Books in Library ===")
    total_books = 0
    for author in authors:
        if author.books:  # Only show authors with books
            print(f"\nBooks by {author.name}:")
            for book in author.books:
                print(f"- {book['title']}")
                for key, value in book.items():
                    if key != 'title':
                        print(f"  {key}: {value}")
                total_books += 1

    if total_books == 0:
        print("No books in the library yet!")
    else:
        print(f"\nTotal books in library: {total_books}")

def search_books_by_author():
    """Allow readers to search for books by author name."""
    if not authors:
        print("\nNo books available in the library!")
        return

    print("\n=== Available Authors ===")
    for i, author in enumerate(authors, 1):
        print(f"{i}. {author.name} ({len(author.books)} books)")

    try:
        choice = int(input("\nSelect author number (or 0 to cancel): "))
        if choice == 0:
            return
        if 1 <= choice <= len(authors):
            authors[choice - 1].display_books()
        else:
            print("Invalid choice!")
    except ValueError:
        print("Please enter a valid number!")

def search_books_by_genre():
    """Allow readers to search for books by genre."""
    if not authors:
        print("\nNo books available in the library!")
        return

    # Collect all unique genres
    genres = set()
    for author in authors:
        for book in author.books:
            if 'genre' in book:
                genres.add(book['genre'])

    if not genres:
        print("\nNo books with genre information available!")
        return

    print("\n=== Available Genres ===")
    for i, genre in enumerate(sorted(genres), 1):
        print(f"{i}. {genre}")

    search_genre = input("\nEnter genre to search for: ").strip()

    print(f"\n=== Books in {search_genre} genre ===")
    found = False
    for author in authors:
        genre_books = [book for book in author.books 
                      if 'genre' in book and book['genre'].lower() == search_genre.lower()]
        if genre_books:
            print(f"\nBy {author.name}:")
            for book in genre_books:
                print(f"- {book['title']}")
                for key, value in book.items():
                    if key not in ['title', 'genre']:
                        print(f"  {key}: {value}")
            found = True

    if not found:
        print(f"No books found in {search_genre} genre.")

def author_session(current_author):
    """Handle the author's session."""
    while True:
        display_author_menu()
        choice = input("Enter your choice (1-5): ")

        if choice == '1':
            # Add new book
            title, book_info = get_book_info()
            current_author.add_book(title, **book_info)
            storage.save_library_data(authors)  # Save after adding

        elif choice == '2':
            # Display author's books
            current_author.display_books()

        elif choice == '3':
            # Update book information
            update_book_menu(current_author)

        elif choice == '4':
            # Remove book
            if not current_author.books:
                print("\nNo books available to remove!")
                continue

            print("\nCurrent books:")
            current_author.display_books()
            title = input("\nEnter the title of the book to remove: ")
            current_author.remove_book(title)
            storage.save_library_data(authors)  # Save after removing

        elif choice == '5':
            # Return to main menu
            return

        else:
            print("\nInvalid choice! Please try again.")

        input("\nPress Enter to continue...")

def reader_session():
    """Handle the reader's session."""
    print("\n=== Reader Login ===")
    reader_name = input("Enter your name: ")
    print(f"\nWelcome, {reader_name}!")

    while True:
        display_reader_menu()
        choice = input("Enter your choice (1-8): ")

        if choice == '1':
            # View all available books
            display_all_books()

        elif choice == '2':
            # Search books by author
            search_books_by_author()

        elif choice == '3':
            # Search books by genre
            search_books_by_genre()

        elif choice == '4':
            # View all authors
            print("\n=== All Authors ===")
            if not authors:
                print("No authors in the library!")
            else:
                for author in authors:
                    print(f"- {author.name} ({len(author.books)} books)")

        elif choice == '5':
            # Borrow a book
            print("\n=== Borrow a Book ===")
            display_all_books()
            isbn = input("\nEnter the ISBN of the book you want to borrow: ")

            # Find the book and check if it's available
            for author in authors:
                for book in author.books:
                    if book.get('isbn') == isbn:
                        if book.get('is_available', True):
                            book['is_available'] = False
                            book['borrower'] = reader_name
                            print(f"\nSuccessfully borrowed '{book['title']}'")
                            storage.save_library_data(authors)  # Save the updated state
                            break
                        else:
                            print("\nSorry, this book is already borrowed.")
                            break
                else:
                    continue
                break
            else:
                print("\nBook not found. Please check the ISBN and try again.")

        elif choice == '6':
            # Return a book
            print("\n=== Return a Book ===")
            borrowed_books = []
            for author in authors:
                for book in author.books:
                    if book.get('borrower') == reader_name:
                        borrowed_books.append((book['title'], book.get('isbn')))

            if not borrowed_books:
                print("You haven't borrowed any books.")
                continue

            print("\nYour borrowed books:")
            for i, (title, isbn) in enumerate(borrowed_books, 1):
                print(f"{i}. {title} (ISBN: {isbn})")

            isbn = input("\nEnter the ISBN of the book you want to return: ")

            # Find the book and return it
            for author in authors:
                for book in author.books:
                    if book.get('isbn') == isbn and book.get('borrower') == reader_name:
                        book['is_available'] = True
                        book['borrower'] = None
                        print(f"\nSuccessfully returned '{book['title']}'")
                        storage.save_library_data(authors)  # Save the updated state
                        break
                else:
                    continue
                break
            else:
                print("\nBook not found in your borrowed books. Please check the ISBN and try again.")

        elif choice == '7':
            # View borrowed books
            print("\n=== Your Borrowed Books ===")
            found = False
            for author in authors:
                for book in author.books:
                    if book.get('borrower') == reader_name:
                        if not found:
                            found = True
                        print(f"\nTitle: {book['title']}")
                        print(f"Author: {author.name}")
                        print(f"ISBN: {book.get('isbn', 'N/A')}")
                        for key, value in book.items():
                            if key not in ['title', 'borrower', 'is_available']:
                                print(f"{key}: {value}")

            if not found:
                print("You haven't borrowed any books.")

        elif choice == '8':
            # Return to main menu
            return

        else:
            print("\nInvalid choice! Please try again.")

        input("\nPress Enter to continue...")

def main():
    # Load existing library data
    global authors
    authors = storage.load_library_data()

    while True:
        display_main_menu()
        choice = input("Enter your choice (1-3): ")

        if choice == '1':
            # Reader mode
            reader_session()

        elif choice == '2':
            # Author mode
            print("\n=== Author Login ===")
            author_name = input("Enter your name: ")

            # Find existing author or create new one
            current_author = next((a for a in authors if a.name.lower() == author_name.lower()), None)
            if current_author is None:
                current_author = Author(author_name)
                authors.append(current_author)
                storage.save_library_data(authors)  # Save after adding new author
                print(f"\nWelcome, new author {author_name}!")
            else:
                print(f"\nWelcome back, {author_name}!")

            author_session(current_author)

        elif choice == '3':
            # Exit
            storage.save_library_data(authors)  # Save before exiting
            print("\nThank you for using the Library Management System!")
            break

        else:
            print("\nInvalid choice! Please try again.")

if __name__ == "__main__":
    main()

